<?php

namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use App\Models\KhqrTransaction;
use App\Models\Order;
use App\Services\KhqrService;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Log;

/**
 * Server-side payment verification against the Bakong Open API.
 *
 * The storefront renders a dynamic KHQR (generated by KhqrService::build()
 * and persisted with its md5 in khqr_transactions). When the cashier asks
 * "did the customer pay?", this controller asks the National Bank of
 * Cambodia directly — NOT the QR string or a client-side report — using the
 * transaction's md5 fingerprint. Only when Bakong confirms the payment do
 * we mark the order PAID.
 */
class PaymentController extends Controller
{
    /**
     * Verify a payment by its KHQR md5 and confirm/finalise the order.
     *
     * POST /api/payments/verify  body: { md5, order_id }
     *
     * Flow:
     *   1. Validate (strict md5 + existing order).
     *   2. The md5 must map to a khqr_transactions row tied to that order
     *      (so one store cannot reuse another's QR).
     *   3. Ask the Bakong Open API: check_transaction_by_md5.
     *   4. On confirmation, persist SUCCESS + PAID atomically (idempotent).
     *   5. Return a clear, stable JSON contract the POS can poll on.
     *
     * @param Request      $request
     * @param KhqrService  $khqr
     *
     * @return JsonResponse statuses: 200 paid, 200 unpaid, 404 unknown
     *                      pair, 422 validation, 502 gateway error,
     *                      503 not configured
     */
    public function verify(Request $request, KhqrService $khqr): JsonResponse
    {
        $validated = $request->validate([
            'md5' => ['required', 'string', 'regex:/^[a-f0-9]{32}$/i'],
            'order_id' => ['required', 'integer', 'exists:orders,order_id'],
        ]);

        // The submitted md5 must belong to a QR we actually issued for
        // this very order. Prevents cross-order reuse of payment hashes.
        $transaction = KhqrTransaction::where('md5', $validated['md5'])
            ->where('order_id', $validated['order_id'])
            ->first();

        if (!$transaction) {
            return response()->json([
                'message' => 'No KHQR transaction matches the provided md5 for this order.',
                'errors' => ['md5' => ['Unknown md5 / order combination.']],
            ], 404);
        }

        // Ask the National Bank of Cambodia whether the payment exists.
        try {
            $result = $khqr->checkPaymentByMd5($validated['md5']);
        } catch (\InvalidArgumentException $e) {
            // Crazy edge — validation already guards this, but never trust.
            return response()->json([
                'message' => 'Invalid md5 format.',
                'errors' => ['md5' => [json_decode($e->getMessage(), true)]],
            ], 422);
        } catch (\RuntimeException $e) {
            // BAKONG_OPEN_API_TOKEN missing.
            Log::error('Bakong Open API not configured at verify time', [
                'md5' => $validated['md5'],
                'order_id' => $validated['order_id'],
            ]);

            return response()->json([
                'message' => 'The Bakong payment gateway is not configured. Contact the administrator.',
                'errors' => ['gateway' => ['Bakong Open API token is missing in the server configuration.']],
            ], 503);
        }

        // Upstream error — keep state untouched and be honest with the
        // cashier instead of leaving them waiting silently.
        if ($result['status'] === 'error') {
            Log::warning('Bakong payment verification failed', [
                'md5' => $validated['md5'],
                'order_id' => $validated['order_id'],
                'result' => collect($result)->except(['md5'])->all(),
            ]);

            return response()->json([
                'message' => $result['message'],
                'data' => [
                    'paid' => false,
                    'status' => $transaction->status,
                    'order_id' => (int) $transaction->order_id,
                ],
            ], 502);
        }

        // Bakong answered but the transaction is not there yet — the
        // customer may still be paying. Leave records as PENDING and let
        // the POS poll again.
        if ($result['status'] === 'unpaid') {
            return response()->json([
                'message' => $result['message'],
                'data' => [
                    'paid' => false,
                    'status' => $transaction->status,
                    'payment_status' => $transaction->order?->payment_status,
                    'order_id' => (int) $transaction->order_id,
                    'reference' => $transaction->reference,
                ],
            ], 200);
        }

        // --- Confirmed by Bakong: persist both rows atomically. --------
        // Idempotent: re-verifying an already-paid order is a no-op.
        $confirmedBakongData = $result['transaction'] ?? [];

        $this->confirmPayment($transaction, (int) $validated['order_id'], $confirmedBakongData);

        return response()->json([
            'message' => 'Payment verified and confirmed.',
            'data' => [
                'paid' => true,
                'status' => 'SUCCESS',
                'payment_status' => 'PAID',
                'order_id' => (int) $validated['order_id'],
                'reference' => $transaction->reference,
                'amount' => $transaction->amount,
                'currency' => $transaction->currency,
                'bakong_hash' => isset($confirmedBakongData['hash']) ? (string) $confirmedBakongData['hash'] : null,
                'bakong_type' => isset($confirmedBakongData['type']) ? (string) $confirmedBakongData['type'] : null,
            ],
        ], 200);
    }

    /**
     * Atomically mark the KHQR transaction SUCCESS and the order PAID.
     *
     * Both flips happen inside one DB transaction; re-runs are harmless
     * because every update is guarded by a "not already set" condition.
     *
     * @param KhqrTransaction $transaction
     * @param int             $orderId
     * @param array           $bakongData  raw transaction object from Bakong
     */
    private function confirmPayment(KhqrTransaction $transaction, int $orderId, array $bakongData): void
    {
        DB::transaction(function () use ($transaction, $orderId, $bakongData) {
            if ($transaction->status !== 'SUCCESS') {
                $transaction->status = 'SUCCESS';
                $transaction->save();
            }

            $order = Order::find($orderId);
            if ($order && $order->payment_status !== 'PAID') {
                $order->payment_status = 'PAID';
                $order->save();
            }

            // Defensive audit: Bakong reports the paid amount/currency.
            // We never BLOCK confirmation on a mismatch (units across the
            // two APIs are prone to minor-unit differences) — we only make
            // it visible in the logs for an operator to investigate.
            if (isset($bakongData['amount'], $bakongData['currency'])) {
                $paidMinor = (int) $bakongData['amount'];
                $expectedMinor = $transaction->currency === 'KHR'
                    ? (int) round($transaction->amount)
                    : (int) round($transaction->amount * 100);

                if ($paidMinor !== $expectedMinor) {
                    Log::warning('KHQR paid amount differs from expected', [
                        'order_id' => $orderId,
                        'reference' => $transaction->reference,
                        'bakong_paid_minor' => $paidMinor,
                        'expected_minor' => $expectedMinor,
                        'bakong_currency' => $bakongData['currency'],
                    ]);
                }
            }
        });
    }
}